var M=(function makeMatcher(){
  const PATHWAYS = ['course', 'career', 'workplace', 'marketplace'];
  const DEST_WORDS = {
    course: ['learn', 'learning', 'course', 'courses', 'training', 'train', 'certificate', 'certification', 'certified', 'programme', 'programmes', 'program', 'lesson', 'lessons', 'study', 'skill', 'skills', 'academy', 'curriculum', 'module', 'modules', 'class', 'classes', 'upskill', 'reskill', 'tutor', 'quiz', 'exam'],
    career: ['career', 'careers', 'job', 'jobs', 'role', 'roles', 'hire', 'hiring', 'recruit', 'recruitment', 'cv', 'resume', 'profile', 'interview', 'promotion', 'competency', 'competencies', 'apprentice', 'apprenticeship', 'internship', 'placement'],
    workplace: ['work', 'workplace', 'workspace', 'project', 'projects', 'assignment', 'assignments', 'gig', 'gigs', 'freelance', 'opportunity', 'opportunities', 'earn', 'earning', 'income', 'employment', 'workforce', 'coworking'],
    marketplace: ['market', 'marketplace', 'sell', 'selling', 'buy', 'buying', 'shop', 'store', 'catalogue', 'catalog', 'trade', 'order', 'orders', 'supplier', 'suppliers', 'vendor', 'buyers', 'listing', 'exchange']
  };
  const ACTIVITY = {learn: 'course', course: 'course', training: 'course', career: 'career', job: 'career', jobs: 'career', work: 'workplace', earn: 'workplace', workplace: 'workplace', sell: 'marketplace', buy: 'marketplace', trade: 'marketplace', marketplace: 'marketplace'};

  const norm = (s) => String(s == null ? '' : s).toLowerCase().replace(/[^a-z0-9]+/g, '');
  const tokens = (text) => String(text || '').toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim().split(' ').filter(Boolean).slice(0, 4000);

  function hashtagsIn(text){
    const out = [];
    const re = /#([A-Za-z][A-Za-z0-9_]{1,60})/g;
    let m;
    while ((m = re.exec(String(text || ''))) && out.length < 200) out.push(m[1]);
    return out;
  }

  // Plural forms find the singular tag: "bakers" finds Baker, "nannies" finds Nanny.
  function singular(k){
    if (k.length > 5 && k.endsWith('ies')) return k.slice(0, -3) + 'y';
    if (k.length > 5 && k.endsWith('ves')) return k.slice(0, -3) + 'fe';
    if (k.length > 4 && /(ches|shes|sses|xes)$/.test(k)) return k.slice(0, -2);
    if (k.length > 4 && k.endsWith('s') && !k.endsWith('ss')) return k.slice(0, -1);
    return k;
  }

  // index = {tags: {tag: [codes]}, names: {word: [codes]}, rank: {code: [shown 1 or 0, place in order]}}
  function matchSector(index, q){
    q = q || {};
    if (q.sector && index.rank[q.sector]) return {code: q.sector, score: 100, by: 'sector'};
    const has = (o, k) => Object.prototype.hasOwnProperty.call(o, k);
    const tagHit = (k) => (has(index.tags, k) && index.tags[k]) || (has(index.tags, singular(k)) && index.tags[singular(k)]) || null;
    const score = {};
    const add = (codes, w) => { for (const c of codes) score[c] = (score[c] || 0) + w; };
    // Each tag counts once, however often it appears, so repeating a word gains nothing.
    const seenTag = {};
    const tagOnce = (k, hit, w) => { const key = singular(k); if (seenTag[key]) return; seenTag[key] = 1; add(hit, w); };
    const tagList = []
      .concat(Array.isArray(q.tags) ? q.tags : String(q.tags || '').split(/[\s,]+/))
      .concat(hashtagsIn(q.text))
      .map((t) => norm(String(t).replace(/^#/, '')))
      .filter(Boolean);
    for (const t of tagList) { const hit = tagHit(t); if (hit) tagOnce(t, hit, 3); }
    // Plain words, and two- and three-word runs written as one tag ("software engineer" finds
    // SoftwareEngineer). The longest run wins, and the words inside it do not count again.
    const w = tokens(q.text);
    for (let i = 0; i < w.length;) {
      let took = 1;
      for (let n = Math.min(3, w.length - i); n >= 1; n--) {
        const k = w.slice(i, i + n).join('');
        if (n === 1 && k.length < 5) continue;
        const hit = tagHit(k);
        if (!hit) continue;
        // A run of words is a strong sign; one word counts fully only when few sectors share it.
        tagOnce(k, hit, n > 1 || hit.length <= 2 ? 2 : 1);
        took = n;
        break;
      }
      i += took;
    }
    // Words of the sector names and the topic words: each counts once, and weighs least.
    const seenName = {};
    for (const word of w) {
      const nk = has(index.names, singular(word)) ? singular(word) : word;
      if (has(index.names, nk) && !seenName[nk]) { seenName[nk] = 1; add(index.names[nk], 1); }
    }
    const codes = Object.keys(score);
    if (!codes.length) return null;
    codes.sort((a, b) => {
      if (score[b] !== score[a]) return score[b] - score[a];
      const ra = index.rank[a] || [0, 0], rb = index.rank[b] || [0, 0];
      if (ra[0] !== rb[0]) return rb[0] - ra[0];
      return (rb[1] || 0) - (ra[1] || 0);
    });
    if (score[codes[0]] < 2) return null; // one stray word is not enough
    return {code: codes[0], score: score[codes[0]], by: tagList.length ? 'hashtags' : 'words'};
  }

  function destinationFor(q){
    q = q || {};
    const act = norm(q.activity);
    if (Object.prototype.hasOwnProperty.call(ACTIVITY, act)) return {type: ACTIVITY[act], by: 'activity'};
    const words = tokens([q.function, q.heading, q.text].filter(Boolean).join(' '));
    const count = {course: 0, career: 0, workplace: 0, marketplace: 0};
    for (const w of words) for (const t of PATHWAYS) if (DEST_WORDS[t].indexOf(w) >= 0) count[t]++;
    let best = null;
    for (const t of PATHWAYS) if (count[t] > 0 && (!best || count[t] > count[best])) best = t;
    return best ? {type: best, by: 'words', words: count[best]} : null; // words: how many of the pathway's words were found
  }

  function timeOf(hour){
    const h = ((Math.floor(Number(hour)) % 24) + 24) % 24;
    if (Number.isNaN(h)) return 'day';
    if (h >= 5 && h < 11) return 'morning';
    if (h >= 11 && h < 17) return 'day';
    return 'evening'; // the evening anchors also serve the night
  }

  return {PATHWAYS, norm, tokens, hashtagsIn, singular, matchSector, destinationFor, timeOf};
})();
/* The page script of the Gandaberunda API. tools/build-static.js wraps this
   file with the site's data (DATA) and the shared matching rules (M), and
   writes one script per site to v1/embed/<site>.js.

   On a site page it:
   1. adds the GROWTH mark to each pane that offers growth, linking straight
      to the matching course pathway, career pathway, workplace or marketplace
      for the pane's sector (from data-sector, hashtags or the pane's words);
   2. fills any element marked data-anchors with the day's anchors as capsules.

   It sends nothing anywhere and sets no cookies. It remembers the
   visitor's last area and which anchors they use for the visit, and keeps
   them in the visitor's own browser only while the visitor's answer to the
   site's privacy notice allows it (DATA.consent).

   It needs no inline code or inline style, so it runs on a site whose
   Content-Security-Policy has no 'unsafe-inline': see addStyle(). */
var doc = document;
var script = doc.currentScript;
var attr = function (n, d) { return (script && script.getAttribute(n)) || d; };
var PANES = attr('data-panes', '[data-growth], main section, main article');
var ANCHORS = attr('data-anchors', '[data-anchors]');
var HEADINGS = 'h1,h2,h3,h4';
var FEW = 6; // up to this many anchors are shown in one row, with no areas to choose from

/* ---------- Where this site's pages are ---------- */
// A site that serves its own copy of this script has its pages two folders above it
// (<site>/v1/embed/<site>.js), wherever the site is mounted: at the root of its domain,
// or under a folder of a host whose address is only a setting. So a script loaded from
// the page's own address links from there. A page elsewhere that borrows the script gets
// links within the site on the site's own domains, and full links to the site otherwise.
// data-links="site" on the script tag always gives full links: for a page that is served
// from the same address as the script but is not part of the site.
function siteBase() {
  if (attr('data-links', '') !== 'site' && script && script.src) {
    try {
      var from = new URL(script.src);
      var at = /^(.*)\/v1\/embed\/[^\/]+$/.exec(from.pathname);
      if (at && from.origin === location.origin) return at[1];
    } catch (e) {}
  }
  return DATA.origins.indexOf(location.origin) >= 0 ? '' : DATA.base;
}
var base = siteBase();

/* ---------- What the script remembers ---------- */
// Always kept for the visit, in memory. Written to the browser only while the
// visitor's choice on the site's privacy notice says yes; after a "Reject all"
// nothing is written, and what an earlier visit wrote is removed.
var memory = {};
function consented() {
  var c = DATA.consent;
  if (!c || !c.key || !c.field) return false;
  try {
    var v = JSON.parse(localStorage.getItem(c.key) || 'null');
    return !!v && v[c.field] === true;
  } catch (e) { return false; }
}
function forget(key) {
  try { localStorage.removeItem('gbd.' + key); } catch (e) {}
}
function store(key, value) {
  var ok = consented();
  if (value === undefined) {
    if (Object.prototype.hasOwnProperty.call(memory, key)) return memory[key];
    if (!ok) { forget(key); return null; }
    try { return JSON.parse(localStorage.getItem('gbd.' + key) || 'null'); } catch (e) { return null; }
  }
  memory[key] = value;
  if (!ok) { forget(key); return null; }
  try { localStorage.setItem('gbd.' + key, JSON.stringify(value)); } catch (e) {}
  return null;
}

function href(type, sector) {
  var map = DATA.paths[type];
  if (!map) return null;
  var path = (sector && map[sector]) || map['*'];
  return path ? base + path : null;
}

function el(tag, cls, text) {
  var e = doc.createElement(tag);
  if (cls) e.className = cls;
  if (text != null) e.textContent = text;
  return e;
}

/* ---------- The script's own look ---------- */
// The rules are in STYLE (from public/embed.css; a site can set --gbd-bg and
// --gbd-ink on .gbd-anchors to give the row its own colours). They go in as a
// constructed style sheet: that needs no <style> tag, so it is allowed where the
// site's Content-Security-Policy has no 'unsafe-inline', and it asks the network
// for nothing. A browser without constructed style sheets loads the same rules
// from gbd.css, which the build writes next to this script.
var styled = false;
